// ── cambiar el color ──────────────────────────────────────────────────────
type HSL = [number, number, number]
function aHsl(hex: string): HSL {
  const n = parseInt(hex.replace('#', '').slice(0, 6), 16)
  const r = ((n >> 16) & 255) / 255, g = ((n >> 8) & 255) / 255, b = (n & 255) / 255
  const max = Math.max(r, g, b), min = Math.min(r, g, b), l = (max + min) / 2
  if (max === min) return [0, 0, l]
  const d = max - min
  const s = l > 0.5 ? d / (2 - max - min) : d / (max + min)
  const h = max === r ? (g - b) / d + (g < b ? 6 : 0) : max === g ? (b - r) / d + 2 : (r - g) / d + 4
  return [h * 60, s, l]
}
function aHex([h, s, l]: HSL): string {
  const k = (n: number) => (n + h / 30) % 12
  const a = s * Math.min(l, 1 - l)
  const f = (n: number) => Math.round(255 * (l - a * Math.max(-1, Math.min(k(n) - 3, Math.min(9 - k(n), 1)))))
  return '#' + [f(0), f(8), f(4)].map(v => v.toString(16).padStart(2, '0')).join('')
}
const lim = (v: number, a: number, b: number) => Math.max(a, Math.min(b, v))
const esBlanco = (hex: string) => { const [, s, l] = aHsl(hex); return l > 0.95 && s < 0.4 }

const cache = new Map<string, string>()
// Devuelve el dibujo listo, con su color original o pasado al color elegido
export function svgConColor(st: StickerCanva, color?: string | null): string {
  if (!st.svg) return ''
  if (!color || color === 'original' || !/^#[0-9a-fA-F]{6}$/.test(color)) return st.svg
  const clave = st.id + color
  const ya = cache.get(clave)
  if (ya) return ya
  const base = aHsl(st.dominante), meta = aHsl(color)
  const out = st.svg.replace(/(fill|stroke)="(#[0-9a-fA-F]{6})"/g, (m, attr: string, hex: string) => {
    if (esBlanco(hex)) return m
    const c = aHsl(hex)
    let dh = c[0] - base[0]; if (dh > 180) dh -= 360; if (dh < -180) dh += 360
    const nuevo: HSL = [(meta[0] + dh * 0.25 + 360) % 360, lim(meta[1] * (base[1] ? c[1] / base[1] : 1), 0, 1), lim(meta[2] + (c[2] - base[2]), 0.06, 0.94)]
    return `${attr}="${aHex(nuevo)}"`
  })
  cache.set(clave, out)
  return out
}
